list_blog_categories.code:
use WebCommander\Sdk\Resources\BlogCategories\BlogCategories;

$response = BlogCategories::listBlogCategories($client, ['limit' => 20, 'offset' => 0]);

foreach ($response->map['blog_categories'] as $category) {
    echo $category['id'], ' ', $category['name'], ' (', $category['url'], ')', PHP_EOL;
}
echo $response->map['pagination']['total'], ' categories in total', PHP_EOL;

create_blog_category.code:
use WebCommander\Sdk\Resources\BlogCategories\BlogCategories;

$response = BlogCategories::createBlogCategory($client, [
