        'name' => 'Seasonal Promotions',
        'url' => 'seasonal-promotions',
        'description' => 'Sale announcements and limited-time offers.',
        'image' => ['file_name' => 'seasonal-promotions.png', 'base64' => 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'title' => 'Seasonal promotions', 'alternative_text' => 'Seasonal promotions banner'],
    ],
