echo $response->map['blog_category']['id'], PHP_EOL;

get_blog_category.code:
use WebCommander\Sdk\Resources\BlogCategories\BlogCategories;

$response = BlogCategories::getBlogCategory($client, 15);

$category = $response->map['blog_category'];
echo $category['name'], ' (', $category['url'], ')', PHP_EOL;
echo $category['description'], PHP_EOL;

